import { Task, TaskStatus, ITaskService, IEventBus, TaskAssignedPayload, TaskStatusChangedPayload } from '../types';
import * as crypto from 'node:crypto';

export class TaskService implements ITaskService {
  private tasks = new Map<string, Task>();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
    // Seed with some initial data for demo/testing
    const task1: Task = { id: crypto.randomUUID(), title: 'Implement Login', description: 'Develop user authentication flow', status: 'todo', assigneeId: null, projectId: 'project1' };
    const task2: Task = { id: crypto.randomUUID(), title: 'Design Database Schema', description: 'Create ER diagrams and define tables', status: 'in-progress', assigneeId: null, projectId: 'project1' };
    this.tasks.set(task1.id, task1);
    this.tasks.set(task2.id, task2);
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const newTask: Task = {
      id: crypto.randomUUID(),
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: null,
      projectId: input.projectId,
    };
    this.tasks.set(newTask.id, newTask);
    return newTask;
  }

  getById(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task with ID ${id} not found`);
    }
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.getById(id);
    if (input.title !== undefined) {
      task.title = input.title;
    }
    if (input.description !== undefined) {
      task.description = input.description;
    }
    this.tasks.set(id, task);
    return task;
  }

  delete(id: string): void {
    if (!this.tasks.has(id)) {
      throw new Error(`Task with ID ${id} not found`);
    }
    this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    const oldAssigneeId = task.assigneeId; // Store old assignee for potential unassignment event

    if (task.assigneeId !== assigneeId) {
      task.assigneeId = assigneeId;
      this.tasks.set(taskId, task);

      const payload: TaskAssignedPayload = {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: assigneeId,
      };
      this.eventBus.publish('task.assigned', payload);
    }

    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldStatus = task.status;

    if (oldStatus === newStatus) {
      return task; // No change
    }

    // Rule 4: FORWARD_ONLY_STATUS
    const validTransitions: { [key in TaskStatus]: TaskStatus[] } = {
      'todo': ['in-progress'],
      'in-progress': ['done'],
      'done': [], // Cannot transition from done
    };

    if (!validTransitions[oldStatus].includes(newStatus)) {
      throw new Error(`Invalid status transition from '${oldStatus}' to '${newStatus}'`);
    }

    task.status = newStatus;
    this.tasks.set(taskId, task);

    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus: oldStatus,
      newStatus: newStatus,
    };
    this.eventBus.publish('task.statusChanged', payload);

    return task;
  }
}

import { Comment, ICommentService, IEventBus, CommentAddedPayload, Task } from '../types';
import * as crypto from 'node:crypto';

interface ITaskServiceForComments { // Mini-interface to avoid direct import of TaskService
  getById(taskId: string): Task;
}

export class CommentService implements ICommentService {
  private comments = new Map<string, Comment>();
  private eventBus: IEventBus;
  private taskService: ITaskServiceForComments; // Dependency for fetching task details

  constructor(eventBus: IEventBus, taskService: ITaskServiceForComments) {
    this.eventBus = eventBus;
    this.taskService = taskService;
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    // Ensure task exists before creating comment
    const task = this.taskService.getById(input.taskId); // Throws if task not found

    const newComment: Comment = {
      id: crypto.randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.comments.set(newComment.id, newComment);

    const payload: CommentAddedPayload = {
      commentId: newComment.id,
      taskId: newComment.taskId,
      authorId: newComment.authorId,
      taskAssigneeId: task.assigneeId, // Pass assigneeId for notification targeting
    };
    this.eventBus.publish('comment.added', payload);

    return newComment;
  }

  getById(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) {
      throw new Error(`Comment with ID ${id} not found`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.has(id)) {
      throw new Error(`Comment with ID ${id} not found`);
    }
    this.comments.delete(id);
  }
}

import { Notification, INotificationService, IUserService, TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload, User, Task } from '../types';
import * as crypto from 'node:crypto';

interface ITaskServiceForNotifications { // Minimal interface for TaskService
  getById(taskId: string): Task;
}

export class NotificationService implements INotificationService {
  private notifications = new Map<string, Notification>();
  private userService: IUserService;
  private taskService: ITaskServiceForNotifications; // To fetch task details for comment notifications

  constructor(userService: IUserService, taskService: ITaskServiceForNotifications) {
    this.userService = userService;
    this.taskService = taskService;
  }

  // This method is called by event subscribers, not directly via API
  createNotification(userId: string, message: string): Notification {
    const newNotification: Notification = {
      id: crypto.randomUUID(),
      userId: userId,
      message: message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    // For in-memory storage, we might want to cap notifications per user or just keep adding
    // For simplicity, just add to the map.
    this.notifications.set(newNotification.id, newNotification);
    return newNotification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values())
      .filter(notification => notification.userId === userId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error(`Notification with ID ${notificationId} not found`);
    }
    notification.read = true;
    this.notifications.set(notificationId, notification);
    return notification;
  }

  // Event Handlers (these will be wired up in main.ts)
  handleTaskAssigned = (payload: unknown) => {
    const assignedPayload = payload as TaskAssignedPayload;
    try {
      const assignee = this.userService.getById(assignedPayload.assigneeId);
      this.createNotification(
        assignedPayload.assigneeId,
        `Task '${assignedPayload.taskTitle}' has been assigned to you.`
      );
    } catch (error) {
      console.error('Error handling task.assigned event:', error);
    }
  };

  handleTaskStatusChanged = (payload: unknown) => {
    const statusChangedPayload = payload as TaskStatusChangedPayload;
    if (statusChangedPayload.assigneeId) {
      try {
        const assignee = this.userService.getById(statusChangedPayload.assigneeId);
        this.createNotification(
          statusChangedPayload.assigneeId,
          `Status of task '${statusChangedPayload.taskTitle}' changed to ${statusChangedPayload.newStatus}.`
        );
      } catch (error) {
        console.error('Error handling task.statusChanged event:', error);
      }
    }
  };

  handleCommentAdded = (payload: unknown) => {
    const commentAddedPayload = payload as CommentAddedPayload;
    // Notify the task assignee if there is one
    if (commentAddedPayload.taskAssigneeId) {
      try {
        const assignee = this.userService.getById(commentAddedPayload.taskAssigneeId);
        // To get the task title for the notification, we need the task service
        const task = this.taskService.getById(commentAddedPayload.taskId);
        const author = this.userService.getById(commentAddedPayload.authorId);
        this.createNotification(
          commentAddedPayload.taskAssigneeId,
          `'${author.name}' commented on your task '${task.title}'.`
        );
      } catch (error) {
        console.error('Error handling comment.added event:', error);
      }
    }
  };
}

import * as http from 'node:http';
import * as url from 'node:url';

import {
  IUserService,
  IProjectService,
  ITaskService,
  ICommentService,
  INotificationService,
  User, Project, Task, Comment, Notification,
  TaskStatus,
} from './types';

interface Services {
  userService: IUserService;
  projectService: IProjectService;
  taskService: ITaskService;
  commentService: ICommentService;
  notificationService: INotificationService;
}

export class Router {
  private services: Services;

  constructor(services: Services) {
    this.services = services;
  }

  private async parseBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let body = '';
      req.on('data', chunk => {
        body += chunk.toString();
      });
      req.on('end', () => {
        if (body) {
          try {
            resolve(JSON.parse(body));
          } catch (error) {
            reject(new Error('Invalid JSON body'));
          }
        } else {
          resolve({});
        }
      });
      req.on('error', reject);
    });
  }

  private sendResponse(res: http.ServerResponse, statusCode: number, data: any) {
    res.setHeader('Content-Type', 'application/json');
    res.writeHead(statusCode);
    res.end(JSON.stringify(data));
  }

  private sendError(res: http.ServerResponse, statusCode: number, message: string) {
    this.sendResponse(res, statusCode, { error: message });
  }

  public async handleRequest(req: http.IncomingMessage, res: http.ServerResponse) {
    const parsedUrl = url.parse(req.url || '', true);
    const path = parsedUrl.pathname;
    const method = req.method;
    const query = parsedUrl.query;

    try {
      let body: any = {};
      if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
        body = await this.parseBody(req);
      }

      if (path === '/users') {
        if (method === 'GET') {
          const users = this.services.userService.getAll();
          return this.sendResponse(res, 200, users);
        } else if (method === 'POST') {
          const newUser = this.services.userService.create(body);
          return this.sendResponse(res, 201, newUser);
        }
      } else if (path?.startsWith('/users/')) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const user = this.services.userService.getById(id);
          return this.sendResponse(res, 200, user);
        } else if (method === 'PUT') {
          const updatedUser = this.services.userService.update(id, body);
          return this.sendResponse(res, 200, updatedUser);
        } else if (method === 'DELETE') {
          this.services.userService.delete(id);
          return this.sendResponse(res, 204, null);
        }
      }

      else if (path === '/projects') {
        if (method === 'GET') {
          const projects = this.services.projectService.getAll();
          return this.sendResponse(res, 200, projects);
        } else if (method === 'POST') {
          const newProject = this.services.projectService.create(body);
          return this.sendResponse(res, 201, newProject);
        }
      } else if (path?.startsWith('/projects/')) {
        const parts = path.split('/');
        const id = parts[2];
        if (method === 'GET') {
          const project = this.services.projectService.getById(id);
          return this.sendResponse(res, 200, project);
        } else if (method === 'PUT') {
          const updatedProject = this.services.projectService.update(id, body);
          return this.sendResponse(res, 200, updatedProject);
        } else if (method === 'DELETE') {
          this.services.projectService.delete(id);
          return this.sendResponse(res, 204, null);
        } else if (parts[3] === 'members') {
          if (method === 'POST') {
            if (!body.userId) {
              throw new Error('userId is required');
            }
            const project = this.services.projectService.addMember(id, body.userId);
            return this.sendResponse(res, 200, project);
          } else if (method === 'DELETE') {
            if (!body.userId) {
              throw new Error('userId is required');
            }
            const project = this.services.projectService.removeMember(id, body.userId);
            return this.sendResponse(res, 200, project);
          }
        }
      }

      else if (path === '/tasks') {
        if (method === 'GET') {
          if (!query.projectId) {
            throw new Error('projectId query parameter is required');
          }
          const tasks = this.services.taskService.getByProject(query.projectId as string);
          return this.sendResponse(res, 200, tasks);
        } else if (method === 'POST') {
          const newTask = this.services.taskService.create(body);
          return this.sendResponse(res, 201, newTask);
        }
      } else if (path?.startsWith('/tasks/')) {
        const parts = path.split('/');
        const id = parts[2];
        if (method === 'GET') {
          const task = this.services.taskService.getById(id);
          return this.sendResponse(res, 200, task);
        } else if (method === 'PUT') {
          if (parts[3] === 'status') {
            if (!body.status) {
              throw new Error('status is required');
            }
            const updatedTask = this.services.taskService.changeStatus(id, body.status as TaskStatus);
            return this.sendResponse(res, 200, updatedTask);
          } else if (parts[3] === 'assign') {
            if (!body.assigneeId) {
              throw new Error('assigneeId is required');
            }
            const updatedTask = this.services.taskService.assign(id, body.assigneeId);
